 "content": "from collections import deque

def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = {(r, c)}
            while q:
                y, x = q.popleft()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        cells.add(p)
                        q.append(p)
            result.append((color, cells))
    return result

def transform(grid):
    out = [row[:] for row in grid]
    comps = components(grid)
    # The large corner-color L is the indicator. Recolor the non-background
    # component that lies closest to it; leave the indicator and background intact.
    markers = [cells for color, cells in comps if color == 9 and len(cells) >= 8]
    if not markers:
        return out
    marker = max(markers, key=len)
    best = None
    best_dist = None
    for color, cells in comps:
        if color == 9:
            continue
        dist = min(abs(r-y)+abs(c-x) for r,c in cells for y,x in marker)
        if best_dist is None or dist < best_dist:
            best_dist, best = dist, (color, cells)
    if best:
        for r, c in best[1]:
            out[r][c] = 9
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
