def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = {(r, c)}
            while q:
                y, x = q.popleft()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        cells.add(p)
                        q.append(p)
            result.append((color, cells))
    return result

def transform(grid):
    out = [row[:] for row in grid]
    comps = components(grid)
    # Find the long L-shaped stroke (signal) and recolor the closest separate
    # colored object to the stroke's color.
    signals = []
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        height, width = max(rs)-min(rs)+1, max(cs)-min(cs)+1
        if len(cells) >= 8 and max(height, width) >= 5 and min(height, width) <= 5:
            signals.append((color, cells, height, width))
    if not signals:
        return out
    color, signal, _, _ = max(signals, key=lambda x: len(x[1]))
    candidates = [(co, cells) for co, cells in comps if cells != signal]
    if not candidates:
        return out
    target_color, target = min(candidates, key=lambda item: min(abs(r-y)+abs(c-x) for r,c in item[1] for y,x in signal))
    for r, c in target:
        out[r][c] = color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
