    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = {(r, c)}
            while q:
                y, x = q.popleft()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        cells.add(p)
                        q.append(p)
            result.append((color, cells))
    return result

def transform(grid):
    out = [row[:] for row in grid]
    comps = components(grid)
    # Find a connected, elongated L-shaped color marker.
    signal = None
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        h, w = max(rs)-min(rs)+1, max(cs)-min(cs)+1
        if len(cells) >= 8 and max(h, w) >= 5 and min(h, w) <= 5:
            # Prefer the object whose bounding box contains two substantial arms.
            if signal is None or len(cells) > len(signal[1]):
                signal = (color, cells)
    if signal is None:
        return out
    color, cells = signal
    # On these L markers, recolor the object touching its vertical arm on the
    # inside-facing side; if absent, leave the grid unchanged.
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    rmin, rmax, cmin, cmax = min(rs), max(rs), min(cs), max(cs)
    vertical = [(r,c) for r,c in cells if c == cmin or c == cmax]
    candidates = []
    for co, obj in comps:
        if obj == cells:
            continue
        contacts = []
        for r,c in obj:
            for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (y,x) in cells:
                    contacts.append(((r,c),(y,x)))
        if contacts:
            # Prefer contacts against the longer vertical arm, then more contacts.
            vcontacts = sum(1 for (r,c),(y,x) in contacts if x in (cmin,cmax) and rmin <= y <= rmax)
            candidates.append((vcontacts, len(contacts), co, obj))
    if candidates:
        _, _, _, target = max(candidates, key=lambda x: (x[0], x[1], len(x[3])))
        for r,c in target:
            out[r][c] = color
