    # directly facing its long horizontal arm, on the open side of the L.
    for color, marker in parts:
        rs=[r for r,c in marker]; cs=[c for r,c in marker]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if len(marker)<8 or r1-r0<3 or c1-c0<4:
