                if color != 2 and color != marker_color:
                    seed = (r, c)
                    q = deque([seed])
                    seen = {seed}
                    while q:
                        y, x = q.popleft()
                        for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            p = (y+dy, x+dx)
                            if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                                    and grid[p[0]][p[1]] == color):
                                seen.add(p)
                                q.append(p)
                    key = frozenset(seen)
                    if key not in changed_components:
                        changed_components.add(key)
                        for y, x in seen:
                            out[y][x] = marker_color
                    break
